[{"order":1,"type":"heading","text":"Spring TestContext Framework Integration with JUnit"},{"order":2,"type":"paragraph","text":"The Spring TestContext Framework provides powerful, annotation-driven unit and integration testing support for Spring applications. In this tutorial, we will explore how to integrate this framework with JUnit to test various layers of a Spring Boot application efficiently using @SpringBootTest and @WebMvcTest."},{"order":3,"type":"subheading","text":"Prerequisites and Setup"},{"order":4,"type":"paragraph","text":"To get started, ensure your project includes the spring-boot-starter-test dependency, which automatically brings in JUnit 5, Mockito, and the Spring TestContext Framework."},{"order":5,"type":"code","text":"dependencies {
    implementation 'org.springframework.boot:spring-boot-starter-web'
    testImplementation 'org.springframework.boot:spring-boot-starter-test'
}"},{"order":6,"type":"subheading","text":"Integration Testing with @SpringBootTest"},{"order":7,"type":"paragraph","text":"The @SpringBootTest annotation tells Spring Boot to look for a main configuration class (one with @SpringBootApplication) and use it to start a Spring application context. This is ideal for full-stack integration tests."},{"order":8,"type":"code","text":"@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class ApplicationIntegrationTest {

    @Autowired
    private TestRestTemplate restTemplate;

    @Test
    void contextLoads() {
        assertNotNull(restTemplate);
    }

    @Test
    void shouldReturnDefaultMessage() {
        String response = restTemplate.getForObject("/api/hello", String.class);
        assertEquals("Hello World", response);
    }
}"},{"order":9,"type":"subheading","text":"Slice Testing with @WebMvcTest"},{"order":10,"type":"paragraph","text":"When you want to test only the web layer without starting the entire application context, use @WebMvcTest. This annotation configures the MVC infrastructure and restricts the classpath scanning to the specified controller."},{"order":11,"type":"code","text":"@WebMvcTest(UserController.class)
class UserControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockBean
    private UserService userService;

    @Test
    void shouldReturnUserById() throws Exception {
        User mockUser = new User(1L, "John Doe");
        given(userService.getUserById(1L)).willReturn(mockUser);

        mockMvc.perform(get("/users/1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.name").value("John Doe"));
    }
}"},{"order":12,"type":"subheading","text":"Key Differences and Best Practices"},{"order":13,"type":"bullet_point","text":"@SpringBootTest loads the complete application context and is slower, but verifies wiring across all components."},{"order":14,"type":"bullet_point","text":"@WebMvcTest loads only the web layer components (Controllers, @ControllerAdvice, Filters), making it much faster for isolated controller testing."},{"order":15,"type":"bullet_point","text":"Use @MockBean to inject mock implementations into the Spring application context for slice tests."}]
